CREATE TYPE "CreativeProjectStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "CreativeJobStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED');
CREATE TYPE "CreativeJobMode" AS ENUM ('GENERATE','EDIT');
CREATE TYPE "CreativeProvider" AS ENUM ('OPENAI');
CREATE TYPE "CreativeAssetStatus" AS ENUM ('READY','DELETED');
CREATE TYPE "CreativeAgentStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TABLE "CreativeTenant" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CreativeTenant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CreativeApiKey" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"name" TEXT NOT NULL,"keyPrefix" TEXT NOT NULL,"keyHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastUsedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),CONSTRAINT "CreativeApiKey_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CreativeProject" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"status" "CreativeProjectStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CreativeProject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GenerationJob" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"mode" "CreativeJobMode" NOT NULL DEFAULT 'GENERATE',"status" "CreativeJobStatus" NOT NULL DEFAULT 'QUEUED',"provider" "CreativeProvider" NOT NULL DEFAULT 'OPENAI',"model" TEXT NOT NULL,"prompt" TEXT NOT NULL,"enhancedPrompt" TEXT,"referenceId" TEXT,"size" TEXT NOT NULL DEFAULT '1024x1024',"quality" TEXT NOT NULL DEFAULT 'high',"outputFormat" TEXT NOT NULL DEFAULT 'webp',"errorCode" TEXT,"errorMessage" TEXT,"attemptCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GenerationJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GeneratedAsset" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"generationJobId" TEXT,"status" "CreativeAssetStatus" NOT NULL DEFAULT 'READY',"storageKey" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"format" TEXT NOT NULL,"width" INTEGER,"height" INTEGER,"byteSize" BIGINT NOT NULL,"sha256" TEXT NOT NULL,"prompt" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMP(3),CONSTRAINT "GeneratedAsset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssetVersion" ("id" TEXT NOT NULL,"assetId" TEXT NOT NULL,"version" INTEGER NOT NULL,"storageKey" TEXT NOT NULL,"prompt" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AssetVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ImageReference" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"byteSize" BIGINT NOT NULL,"sha256" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ImageReference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PromptTemplate" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT,"name" TEXT NOT NULL,"prompt" TEXT NOT NULL,"variables" JSONB,"isShared" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PromptTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AgentExecution" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"jobId" TEXT,"agentName" TEXT NOT NULL,"status" "CreativeAgentStatus" NOT NULL DEFAULT 'QUEUED',"input" JSONB,"output" JSONB,"error" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AgentExecution_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GenerationUsage" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"jobId" TEXT NOT NULL,"provider" "CreativeProvider" NOT NULL,"model" TEXT NOT NULL,"outputCount" INTEGER NOT NULL DEFAULT 1,"outputBytes" BIGINT NOT NULL DEFAULT 0,"estimatedCostUsd" DECIMAL(12,6),"providerRequestId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GenerationUsage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"actorKeyId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
